// VerifyModuleNameSecurity проверяет защищенность имени модуля от Dependency Confusion
func VerifyModuleNameSecurity(modulePath string, corporateDomains []string) (bool, string) {
	// 1. Проверка на плоские имена без домена (запрещено в современном Go)
	if !strings.Contains(modulePath, ".") || !strings.Contains(modulePath, "/") {
		return false, fmt.Sprintf("INSECURE: Module %q lacks FQDN domain prefix (High risk of collision)", modulePath)
	}

	// 2. Проверка соответствия корпоративному домену
	isCorporate := false
	for _, domain := range corporateDomains {
		if strings.HasPrefix(modulePath, domain+"/") {
			isCorporate = true
			break
		}
	}

	if isCorporate {
		return true, fmt.Sprintf("SECURE: %q belongs to verified corporate domain namespace. Protected by GOPRIVATE.", modulePath)
	}

	return true, fmt.Sprintf("PUBLIC: %q is treated as public third-party dependency. Protected by sum.golang.org.", modulePath)
}

