import (
	"fmt"
	"strconv"
	"strings"
)

// SemVer представляет упрощенную семантическую версию
type SemVer struct {
	Major int
	Minor int
	Patch int
}

func ParseSemVer(v string) SemVer {
	v = strings.TrimPrefix(v, "v")
	parts := strings.Split(v, ".")
	maj, _ := strconv.Atoi(parts[0])
	min, patch := 0, 0
	if len(parts) > 1 {
		min, _ = strconv.Atoi(parts[1])
	}
	if len(parts) > 2 {
		patch, _ = strconv.Atoi(parts[2])
	}
	return SemVer{Major: maj, Minor: min, Patch: patch}
}

func (s SemVer) Compare(other SemVer) int {
	if s.Major != other.Major {
		return s.Major - other.Major
	}
	if s.Minor != other.Minor {
		return s.Minor - other.Minor
	}
	return s.Patch - other.Patch
}

func (s SemVer) String() string {
	return fmt.Sprintf("v%d.%d.%d", s.Major, s.Minor, s.Patch)
}

// ResolveMVS находит максимальную из минимально заявленных версий
func ResolveMVS(requirements map[string][]string) map[string]SemVer {
	selected := make(map[string]SemVer)

	for mod, versions := range requirements {
		for _, vStr := range versions {
			v := ParseSemVer(vStr)
			current, exists := selected[mod]
			if !exists || v.Compare(current) > 0 {
				selected[mod] = v
			}
		}
	}
	return selected
}

func main() {
	// Моделируем требования модулей:
	// Module A требует logging v1.2.0
	// Module B требует logging v1.4.0
	// В репозитории logging доступна v1.9.0 (но MVS ее проигнорирует!)
	requirements := map[string][]string{
		"github.com/corp/logging": {"v1.2.0", "v1.4.0"},
		"github.com/corp/auth":    {"v2.1.0", "v2.0.5"},
	}

	result := ResolveMVS(requirements)
	fmt.Println("MVS Selected Versions (Minimal Version Selection):")
	for mod, ver := range result {
		fmt.Printf("  Module: %-25s -> Selected: %s (Ignored available v1.9.0)\n", mod, ver)
	}
	fmt.Println("\nMVS guarantees absolute reproducibility: builds never change without explicit developer action.")
}

