package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

// HashNode вычисляет промежуточный хэш Меркла: SHA256(0x01 || left || right)
func HashNode(left, right []byte) []byte {
	h := sha256.New()
	h.Write([]byte{0x01}) // Префикс узла для защиты от collision attacks
	h.Write(left)
	h.Write(right)
	return h.Sum(nil)
}

// HashLeaf вычисляет хэш листа: SHA256(0x00 || data)
func HashLeaf(data []byte) []byte {
	h := sha256.New()
	h.Write([]byte{0x00}) // Префикс листа
	h.Write(data)
	return h.Sum(nil)
}

func main() {
	// 4 записи о версиях библиотек
	leaf1 := HashLeaf([]byte("github.com/gin-gonic/gin v1.9.0 h1:abc1"))
	leaf2 := HashLeaf([]byte("github.com/google/uuid v1.6.0 h1:abc2"))
	leaf3 := HashLeaf([]byte("go.uber.org/zap v1.27.0 h1:abc3"))
	leaf4 := HashLeaf([]byte("golang.org/x/crypto v0.21.0 h1:abc4"))

	// Строим дерево Меркла
	parent1 := HashNode(leaf1, leaf2)
	parent2 := HashNode(leaf3, leaf4)
	treeRoot := HashNode(parent1, parent2)

	fmt.Printf("Signed Tree Head (Merkle Root): %s\n", hex.EncodeToString(treeRoot))

	// Доказательство включения для leaf1: требуются leaf2 и parent2
	recomputedParent1 := HashNode(leaf1, leaf2)
	recomputedRoot := HashNode(recomputedParent1, parent2)

	if hex.EncodeToString(recomputedRoot) == hex.EncodeToString(treeRoot) {
		fmt.Println("Cryptographic Proof of Inclusion verified: Module is immutably logged in SumDB!")
	}
}

